ides","Haloalkanes"],"difficulty":5,"importance":6},{"name":"Reaction Types","subtopics":["Addition","Substitution","Elimination","Condensation","Hydrolysis","Oxidation","Reduction"],"difficulty":5,"importance":6},{"name":"Isomerism","subtopics":["Structural isomerism","Stereoisomerism","Cis-trans isomerism","Optical isomerism (HL)"],"difficulty":5,"importance":6},{"name":"Paper 1","subtopics":["Multiple-choice questions","Conceptual understanding"],"difficulty":5,"importance":6},{"name":"Paper 2","subtopics":["Structured calculations","Chemical explanations","Multi-step problem solving"],"difficulty":5,"importance":6},{"name":"Paper 3 (HL, where applicable)","subtopics":["Experimental analysis","Data-based questions","Advanced HL content"],"difficulty":5,"importance":6},{"name":"Required Skills","subtopics":["Balance equations","Perform stoichiometric calculations","Interpret spectra","Analyze reaction mechanisms","Evaluate experimental data","Design investigations","Apply chemical models","Justify conclusions using evidence"],"difficulty":5,"importance":6}]'::jsonb, 'official');
